import Component from "flarum/common/Component";
import Switch from "flarum/common/components/Switch";
import { settings, saveSetting, getBool } from "../utils/settings";
/**
 * A boolean settings toggle that auto-saves on change. Mutates the live
 * `app.data.settings` map so other components reading the same key reflect
 * the new value before the API roundtrip resolves.
 */
export default class AdminToggle extends Component {
  view() {
    const {
      settingKey,
      label,
      help
    } = this.attrs;
    const value = getBool(settingKey);
    return m("div", {
      className: "Form-group VerifiedAdmin-toggle"
    }, m(Switch, {
      state: value,
      onchange: checked => {
        settings()[settingKey] = checked;
        m.redraw();
        saveSetting({
          [settingKey]: checked ? "1" : "0"
        });
      }
    }, label), help && m("p", {
      className: "helpText"
    }, help));
  }
}
flarum.reg.add('ramon-verified', 'admin/components/AdminToggle', AdminToggle);